 4	public final class BipartiteGraph {
 5	    private BipartiteGraph() {
 6	        // Utility class.
 7	    }
 8	
 9	    public static boolean isBipartite(int vertexCount, int[][] edges) {
10	        return isBipartite(Graph.fromEdges(vertexCount, edges));
11	    }
12	
13	    public static boolean isBipartite(Graph graph) {
14	        ColoringState coloring = new ColoringState(graph.vertexCount());
15	
16	        for (int vertex : graph) {
17	            if (!coloring.isColored(vertex)
18	                    && !isComponentBipartite(vertex, graph, coloring)) {
19	                return false;
20	            }
21	        }
22	
23	        return true;
24	    }
25	
26	    private static boolean isComponentBipartite(
27	            int startVertex,
28	            Graph graph,
29	            ColoringState coloring) {
30	        Deque<Integer> queue = new ArrayDeque<>();
31	        coloring.colorStartVertex(startVertex);
32	        queue.offer(startVertex);
33	
34	        while (!queue.isEmpty()) {
35	            int currentVertex = queue.poll();
36	
37	            for (int neighbor : graph.neighborsOf(currentVertex)) {
38	                if (!coloring.isColored(neighbor)) {
39	                    coloring.colorWithOpposite(neighbor, currentVertex);
40	                    queue.offer(neighbor);
41	                    continue;
42	                }
43	
44	                if (coloring.hasSameColor(currentVertex, neighbor)) {
45	                    return false;
46	                }
47	            }
48	        }
49	
50	        return true;
51	    }
52	
53	    private enum VertexColor {
54	        FIRST,
55	        SECOND;
56	
57	        VertexColor opposite() {
58	            return this == FIRST ? SECOND : FIRST;
59	        }
60	    }
61	
62	    private static final class ColoringState {
63	        private final VertexColor[] colors;
64	
65	        private ColoringState(int vertexCount) {
66	            this.colors = new VertexColor[vertexCount];
67	        }
68	
69	        private boolean isColored(int vertex) {
70	            return colors[vertex] != null;
71	        }
72	
73	        private void colorStartVertex(int vertex) {
74	            colors[vertex] = VertexColor.FIRST;
75	        }
76	
77	        private void colorWithOpposite(int vertex, int referenceVertex) {
78	            colors[vertex] = colors[referenceVertex].opposite();
79	        }
80	
81	        private boolean hasSameColor(int firstVertex, int secondVertex) {
82	            return colors[firstVertex] == colors[secondVertex];
83	        }
84	    }
85	}

