 97	    private static void assertThrows(
 98	            Class<? extends Throwable> expectedType,
 99	            ThrowingRunnable action,
100	            String message) {
101	        try {
102	            action.run();
103	        } catch (Throwable throwable) {
104	            if (expectedType.isInstance(throwable)) {
105	                return;
106	            }
107	
108	            throw new AssertionError(
109	                    message
110	                            + " Expected exception: "
111	                            + expectedType.getSimpleName()
112	                            + ", actual: "
113	                            + throwable.getClass().getSimpleName(),
114	                    throwable);
115	        }
116	
117	        throw new AssertionError(
118	                message + " Expected exception: " + expectedType.getSimpleName() + ".");
119	    }
